async fn spawn_delayed_request_recorder(
    response: Value,
    delay: Duration,
) -> (
    String,
    Arc<tokio::sync::Mutex<Vec<Value>>>,
    tokio::task::JoinHandle<()>,
) {
    let requests = Arc::new(tokio::sync::Mutex::new(Vec::new()));
    let handler_requests = Arc::clone(&requests);
    let app = axum::Router::new().fallback(axum::routing::post(
        move |headers: http::HeaderMap, uri: http::Uri, axum::Json(payload): axum::Json<Value>| {
            let requests = Arc::clone(&handler_requests);
            let response = response.clone();
            async move {
                let headers = headers
                    .iter()
                    .filter_map(|(name, value)| {
                        value
                            .to_str()
                            .ok()
                            .map(|value| (name.as_str().to_string(), json!(value)))
                    })
                    .collect::<serde_json::Map<_, _>>();
                requests.lock().await.push(json!({
                    "uri": uri.path_and_query().map(|value| value.as_str()).unwrap_or("/"),
                    "headers": headers,
                    "payload": payload
                }));
                sleep(delay).await;
                axum::Json(response)
            }
        },
    ));
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let addr = listener.local_addr().unwrap();
    let task = tokio::spawn(async move {
        axum::serve(listener, app).await.unwrap();
    });
    (format!("http://{addr}"), requests, task)
}

async fn spawn_delayed_dynamic_embedding_recorder(
    delay: Duration,
) -> (
    String,
    Arc<tokio::sync::Mutex<Vec<Value>>>,
    tokio::task::JoinHandle<()>,
) {
    let requests = Arc::new(tokio::sync::Mutex::new(Vec::new()));
    let handler_requests = Arc::clone(&requests);
    let app = axum::Router::new().fallback(axum::routing::post(
        move |headers: http::HeaderMap, uri: http::Uri, axum::Json(payload): axum::Json<Value>| {
            let requests = Arc::clone(&handler_requests);
            async move {
                let headers = headers
                    .iter()
                    .filter_map(|(name, value)| {
                        value
                            .to_str()
                            .ok()
                            .map(|value| (name.as_str().to_string(), json!(value)))
                    })
                    .collect::<serde_json::Map<_, _>>();
                requests.lock().await.push(json!({
                    "uri": uri.path_and_query().map(|value| value.as_str()).unwrap_or("/"),
                    "headers": headers,
                    "payload": payload
                }));
                sleep(delay).await;
                let input_count = payload["input"]
                    .as_array()
                    .map(|items| items.len())
                    .unwrap_or(1)
                    .max(1);
                let data = (0..input_count)
                    .map(|index| {
                        json!({
                            "object": "embedding",
                            "index": index,
                            "embedding": [1.0, index as f64, 0.0]
                        })
                    })
                    .collect::<Vec<_>>();
                axum::Json(json!({
                    "object": "list",
                    "data": data,
                    "model": "text-embedding-3-small",
                    "usage": {"prompt_tokens": input_count, "total_tokens": input_count}
                }))
            }
        },
    ));
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let addr = listener.local_addr().unwrap();
    let task = tokio::spawn(async move {
        axum::serve(listener, app).await.unwrap();
    });
    (format!("http://{addr}"), requests, task)
}

async fn spawn_semantic_embedding_mock() -> (
    String,
    Arc<tokio::sync::Mutex<Vec<Value>>>,
    tokio::task::JoinHandle<()>,
) {
    let requests = Arc::new(tokio::sync::Mutex::new(Vec::new()));
    let handler_requests = Arc::clone(&requests);
    let app = axum::Router::new().route(
        "/v1/embeddings",
        axum::routing::post(move |axum::Json(payload): axum::Json<Value>| {
            let requests = Arc::clone(&handler_requests);
            async move {
                requests.lock().await.push(payload.clone());
                let inputs = match &payload["input"] {
                    Value::Array(items) => items
                        .iter()
                        .filter_map(Value::as_str)
                        .map(ToString::to_string)
                        .collect::<Vec<_>>(),
                    Value::String(value) => vec![value.to_string()],
                    _ => Vec::new(),
                };
                let data = inputs
                    .iter()
                    .enumerate()
                    .map(|(index, text)| {
                        let lower = text.to_lowercase();
                        let embedding = if lower.contains("semantic-only answer")
                            || lower.contains("semantic target")
                        {
                            vec![1.0, 0.0, 0.0]
                        } else if lower.contains("lexical trap") {
                            vec![0.0, 1.0, 0.0]
                        } else {
                            vec![0.0, 0.0, 1.0]
                        };
                        json!({
                            "object": "embedding",
                            "index": index,
                            "embedding": embedding
                        })
                    })
                    .collect::<Vec<_>>();
                axum::Json(json!({
                    "object": "list",
                    "data": data,
                    "model": "text-embedding-3-small",
                    "usage": {"prompt_tokens": inputs.len(), "total_tokens": inputs.len()}
                }))
            }
        }),
    );
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let addr = listener.local_addr().unwrap();
    let task = tokio::spawn(async move {
        axum::serve(listener, app).await.unwrap();
    });
    (format!("http://{addr}/v1"), requests, task)
}

