async fn create_markdown_knowledge_base(
    app: axum::Router,
    name: &str,
    filename: &str,
    content: &str,
) {
    let _ =
        create_markdown_knowledge_base_at(app, "/api/v1/knowledge/create", name, filename, content)
            .await;
}

async fn create_markdown_knowledge_base_at(
    app: axum::Router,
    uri: &str,
    name: &str,
    filename: &str,
    content: &str,
) -> Value {
    let boundary = format!(
        "SOCARTESCOURSE{}",
        TEST_ROOT_COUNTER.fetch_add(1, Ordering::Relaxed)
    );
    let mut body = Vec::new();
    push_multipart_text(&mut body, &boundary, "name", name);
    push_multipart_file(
        &mut body,
        &boundary,
        "files",
        filename,
        "text/markdown",
        content.as_bytes(),
    );
    finish_multipart(&mut body, &boundary);
    let response = app
        .oneshot(
            http::Request::builder()
                .method("POST")
                .uri(uri)
                .header(
                    http::header::CONTENT_TYPE,
                    format!("multipart/form-data; boundary={boundary}"),
                )
                .body(Body::from(body))
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(response.status(), http::StatusCode::OK);
    json_response(response).await
}

fn parse_sse_data_events(body: &str) -> Vec<Value> {
    body.split("\n\n")
        .filter_map(|block| {
            block
                .lines()
                .find_map(|line| line.strip_prefix("data: "))
                .map(|data| serde_json::from_str::<Value>(data).expect("sse data json"))
        })
        .collect()
}

fn parse_sse_events(body: &str) -> Vec<(String, Value)> {
    body.split("\n\n")
        .filter_map(|block| {
            let event = block
                .lines()
                .find_map(|line| line.strip_prefix("event: "))?;
            let data = block.lines().find_map(|line| line.strip_prefix("data: "))?;
            Some((
                event.to_string(),
                serde_json::from_str::<Value>(data).expect("sse data json"),
            ))
        })
        .collect()
}

