#[tokio::test]
async fn chat_ws_subscribe_turn_continues_with_live_events_for_running_turn() {
    let root = unique_test_knowledge_root();
    let server_root = root.clone();
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let addr = listener.local_addr().unwrap();
    let server = tokio::spawn(async move {
        axum::serve(listener, app_with_knowledge_root(server_root))
            .await
            .unwrap();
    });

    let (mut starter_socket, _) = connect_async(format!("ws://{addr}/api/v1/ws"))
        .await
        .unwrap();
    starter_socket
        .send(TungsteniteMessage::Text(
            json!({
                "type": "start_turn",
                "content": "Explain live Socartes websocket subscriptions.",
                "language": "en",
                "knowledge_bases": ["socartes-rust-rag"],
                "config": { "debug_stream_delay_ms": 25 }
            })
            .to_string()
            .into(),
        ))
        .await
        .unwrap();

    let first_message = timeout(Duration::from_secs(2), starter_socket.next())
        .await
        .expect("first websocket event")
        .expect("socket message")
        .expect("valid socket message");
    let TungsteniteMessage::Text(first_text) = first_message else {
        panic!("expected text websocket message");
    };
    let session_event: Value = serde_json::from_str(&first_text).unwrap();
    assert_eq!(session_event["type"], "session");
    let session_id = session_event["session_id"].as_str().unwrap().to_string();
    let turn_id = session_event["turn_id"].as_str().unwrap().to_string();

    let (mut subscriber_socket, _) = connect_async(format!("ws://{addr}/api/v1/ws"))
        .await
        .unwrap();
    subscriber_socket
        .send(TungsteniteMessage::Text(
            json!({
                "type": "subscribe_turn",
                "turn_id": turn_id,
                "after_seq": 1
            })
            .to_string()
            .into(),
        ))
        .await
        .unwrap();

    let mut subscriber_events = Vec::new();
    loop {
        let message = timeout(Duration::from_secs(2), subscriber_socket.next())
            .await
            .expect("live subscription should finish")
            .expect("socket message")
            .expect("valid socket message");
        match message {
            TungsteniteMessage::Text(text) => {
                let event: Value = serde_json::from_str(&text).unwrap();
                let done = event["type"] == "done";
                subscriber_events.push(event);
                if done {
                    break;
                }
            }
            TungsteniteMessage::Close(_) => break,
            _ => {}
        }
    }

    server.abort();
    assert_eq!(
        subscriber_events
            .iter()
            .map(|event| event["seq"].as_u64().unwrap())
            .collect::<Vec<_>>(),
        vec![2, 3, 4, 5, 6, 7]
    );
    assert!(
        subscriber_events
            .iter()
            .all(|event| event["session_id"] == session_id)
    );
    assert!(
        subscriber_events
            .iter()
            .all(|event| event["turn_id"] == turn_id)
    );
    assert_eq!(
        subscriber_events.last().unwrap()["metadata"]["status"],
        "completed"
    );

    let detail_response = app_with_knowledge_root(&root)
        .oneshot(
            http::Request::builder()
                .uri(format!("/api/v1/sessions/{session_id}"))
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(detail_response.status(), http::StatusCode::OK);
    let detail = json_response(detail_response).await;
    let matching_turns = detail["turns"]
        .as_array()
        .unwrap()
        .iter()
        .filter(|turn| turn["id"] == turn_id)
        .collect::<Vec<_>>();
    assert_eq!(matching_turns.len(), 1);
    assert_eq!(matching_turns[0]["status"], "completed");

    let _ = std::fs::remove_dir_all(test_data_root(&root));
}

#[tokio::test]
async fn chat_ws_streams_rag_thinking_before_slow_llm_finishes() {
    let root = unique_test_knowledge_root();
    let (llm_base_url, requests, llm_server) = spawn_delayed_request_recorder(
        json!({
            "id": "slow-chat-rag",
            "object": "chat.completion",
            "choices": [{
                "index": 0,
                "message": {
                    "role": "assistant",
                    "content": "The delayed provider answer confirms the saffron matrix key."
                },
                "finish_reason": "stop"
            }]
        }),
        Duration::from_millis(800),
    )
    .await;
    let app = app_with_knowledge_root(&root);
    let catalog_response = app
        .clone()
        .oneshot(
            http::Request::builder()
                .method("PUT")
                .uri("/api/v1/settings/catalog")
                .header("content-type", "application/json")
                .body(Body::from(
                    json!({ "catalog": llm_test_catalog(&format!("{llm_base_url}/v1")) })
                        .to_string(),
                ))
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(catalog_response.status(), http::StatusCode::OK);
    create_markdown_knowledge_base(
        app.clone(),
        "slow-rag-course",
        "slow-rag.md",
        "The obsidian syllabus key is saffron matrix, and only this course file names it.",
    )
    .await;

    let server_root = root.clone();
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let addr = listener.local_addr().unwrap();
    let server = tokio::spawn(async move {
        axum::serve(listener, app_with_knowledge_root(server_root))
            .await
            .unwrap();
    });

    let (mut socket, _) = connect_async(format!("ws://{addr}/api/v1/ws"))
        .await
        .unwrap();
    socket
        .send(TungsteniteMessage::Text(
            json!({
                "type": "start_turn",
                "content": "What is the obsidian syllabus key?",
                "language": "en",
                "tools": ["rag"],
                "knowledge_bases": ["slow-rag-course"],
                "llm_selection": {
                    "profile_id": "mock-llm",
                    "model_id": "mock-model"
                }
            })
            .to_string()
            .into(),
        ))
        .await
        .unwrap();

    let mut events = Vec::new();
    for _ in 0..4 {
        let message = timeout(Duration::from_millis(250), socket.next())
            .await
            .expect("chat should stream process events before the slow LLM responds")
            .expect("socket message")
            .expect("valid socket message");
        let TungsteniteMessage::Text(text) = message else {
            continue;
        };
        let event: Value = serde_json::from_str(&text).unwrap();
        events.push(event);
        if events.iter().any(|event| {
            matches!(
                event["type"].as_str(),
                Some("thinking" | "progress" | "tool_call")
            ) && event["stage"] == "rag"
        }) {
            break;
        }
    }
    assert!(
        events.iter().any(|event| {
            matches!(
                event["type"].as_str(),
                Some("thinking" | "progress" | "tool_call")
            ) && event["stage"] == "rag"
        }),
        "RAG turns should expose retrieval process events before the final provider answer"
    );

    events.extend(collect_ws_json_until(&mut socket, "done").await);
    assert!(
        events.iter().any(|event| {
            event["type"] == "sources"
                && event["metadata"]["sources"]
                    .as_array()
                    .is_some_and(|sources| {
                        sources.iter().any(|source| {
                            source["source_id"]
                                .as_str()
                                .is_some_and(|id| id.starts_with("slow-rag-course/slow-rag.md"))
                                && source["content"]
                                    .as_str()
                                    .is_some_and(|content| content.contains("saffron matrix"))
                        })
                    })
        }),
        "events: {}",
        serde_json::to_string_pretty(&events).unwrap()
    );
    let content = events
        .iter()
        .filter(|event| event["type"] == "content")
        .filter_map(|event| event["content"].as_str())
        .collect::<String>();
    assert!(content.contains("saffron matrix key"));
    assert_eq!(requests.lock().await.len(), 1);

    server.abort();
    llm_server.abort();
    let _ = std::fs::remove_dir_all(test_data_root(&root));
}

#[tokio::test]
async fn chat_ws_start_socket_disconnect_does_not_truncate_persisted_turn_events() {
    let root = unique_test_knowledge_root();
    let server_root = root.clone();
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let addr = listener.local_addr().unwrap();
    let server = tokio::spawn(async move {
        axum::serve(listener, app_with_knowledge_root(server_root))
            .await
            .unwrap();
    });

    let (mut starter_socket, _) = connect_async(format!("ws://{addr}/api/v1/ws"))
        .await
        .unwrap();
    starter_socket
        .send(TungsteniteMessage::Text(
            json!({
                "type": "start_turn",
                "content": "Explain disconnect-safe Socartes websocket persistence.",
                "language": "en",
                "knowledge_bases": ["socartes-rust-rag"],
                "config": { "debug_stream_delay_ms": 10 }
            })
            .to_string()
            .into(),
        ))
        .await
        .unwrap();

    let first_message = timeout(Duration::from_secs(2), starter_socket.next())
        .await
        .expect("first websocket event")
        .expect("socket message")
        .expect("valid socket message");
    let TungsteniteMessage::Text(first_text) = first_message else {
        panic!("expected text websocket message");
    };
    let session_event: Value = serde_json::from_str(&first_text).unwrap();
    assert_eq!(session_event["type"], "session");
    let turn_id = session_event["turn_id"].as_str().unwrap().to_string();
    starter_socket.close(None).await.unwrap();
    tokio::time::sleep(Duration::from_millis(120)).await;

    let (mut replay_socket, _) = connect_async(format!("ws://{addr}/api/v1/ws"))
        .await
        .unwrap();
    replay_socket
        .send(TungsteniteMessage::Text(
            json!({
                "type": "subscribe_turn",
                "turn_id": turn_id,
                "after_seq": 0
            })
            .to_string()
            .into(),
        ))
        .await
        .unwrap();

    let mut replay_events = Vec::new();
    loop {
        let message = timeout(Duration::from_secs(2), replay_socket.next())
            .await
            .expect("replay should finish after starter disconnect")
            .expect("socket message")
            .expect("valid socket message");
        match message {
            TungsteniteMessage::Text(text) => {
                let event: Value = serde_json::from_str(&text).unwrap();
                let done = event["type"] == "done";
                replay_events.push(event);
                if done {
                    break;
                }
            }
            TungsteniteMessage::Close(_) => break,
            _ => {}
        }
    }

    server.abort();
    assert_eq!(
        replay_events
            .iter()
            .map(|event| event["seq"].as_u64().unwrap())
            .collect::<Vec<_>>(),
        vec![1, 2, 3, 4, 5, 6, 7]
    );
    assert_eq!(replay_events.last().unwrap()["type"], "done");
    assert_eq!(
        replay_events.last().unwrap()["metadata"]["status"],
        "completed"
    );

    let _ = std::fs::remove_dir_all(test_data_root(&root));
}

